use rustler::{Atom, Env, NifResult, Term};
use std::sync::{Arc, RwLock};
use std::collections::HashMap;
use tree_sitter::{Language, Parser, Node, Tree};
use crate::ast_node::AstNode;

/// Registry for language grammars.
pub struct ParserManager {
    grammars: Arc<RwLock<HashMap<String, Language>>>,
}

impl ParserManager {
    pub fn new() -> Self {
        let mut grammars = HashMap::new();
        // Register supported grammars (Elixir initialized by example)
        // Note: Actual .so loading would happen here or in a pre-init hook.
        // For this implementation, we assume static linking or pre-loaded grammars.
        grammars.insert("elixir".to_string(), tree_sitter_elixir::language());

        Self {
            grammars: Arc::new(RwLock::new(grammars)),
        }
    }

    pub fn get_language(&self, lang: &str) -> Option<Language> {
        self.grammars.read().ok()?.get(lang).cloned()
    }
}

/// Entry point for parsing source code via NIF.
#[rustler::nif]
pub fn parse_source(env: Env, lang_atom: Atom, source_code: String) -> NifResult<Term> {
    let lang_name = lang_atom.to_string();

    // 1. Resolve language grammar
    let language = match get_global_parser_manager().get_language(&lang_name) {
        Some(l) => l,
        None => return Err(rustler::Error::Term(Box::new("language_not_supported"))),
    };

    // 2. Perform parsing in a scoped thread to protect BEAM scheduler
    let result = std::panic::catch_unwind(|| {
        let mut parser = Parser::new();
        parser.set_language(language).map_err(|_| "grammar_load_error")?;

        let tree = parser.parse(&source_code, None).ok_or("parsing_failed")?;
        let root = tree.root_node();

        Ok(walk_node(root, &source_code, &lang_name))
    });

    match result {
        Ok(Ok(ast)) => Ok(ast.encode(env)),
        Ok(Err(e)) => Err(rustler::Error::Term(Box::new(e))),
        Err(_) => Err(rustler::Error::Term(Box::new("parser_panic"))),
    }
}

/// Recursively walks the tree-sitter node structure.
fn walk_node(node: Node, source: &str, file_path: &str) -> AstNode {
    let mut children = Vec::new();
    let mut cursor = node.walk();

    for child in node.children(&mut cursor) {
        children.push(walk_node(child, source, file_path));
    }

    let start = node.start_position();
    let end = node.end_position();

    AstNode {
        node_type: node.kind().to_string(),
        content: node.utf8_text(source.as_bytes()).unwrap_or("").to_string(),
        file_path: file_path.to_string(),
        start_line: start.row + 1,
        start_col: start.column + 1,
        end_line: end.row + 1,
        end_col: end.column + 1,
        children,
    }
}

/// Global instance of the parser manager.
fn get_global_parser_manager() -> &'static ParserManager {
    use std::sync::OnceLock;
    static MANAGER: OnceLock<ParserManager> = OnceLock::new();
    MANAGER.get_or_init(ParserManager::new)
}

#[cfg(test)]
mod tests {
    use crate::parser::{parse_source, ParserManager};
    use crate::ast_node::AstNode;
    use rustler::{Env, Atom};
    use std::sync::{Arc, Barrier};
    use std::thread;
    use std::time::Duration;

    /// Helper to mock a minimal Rustler environment.
    fn mock_env() -> Env<'static> {
        unsafe { rustler::env::OwnedEnv::new().env() }
    }

    #[test]
    fn test_parse_elixir_simple_module() {
        let env = mock_env();
        let lang = Atom::from_str(env, "elixir").unwrap();
        let source = "defmodule Test do end";

        let result = parse_source(env, lang, source.to_string());
        assert!(result.is_ok(), "Parsing should succeed for valid Elixir code");
    }

    #[test]
    fn test_parse_complex_nested_structure() {
        let env = mock_env();
        let lang = Atom::from_str(env, "elixir").unwrap();
        let source = "
            defmodule Nested do
                def func(a) do
                    case a do
                        true -> :ok
                        _ -> :error
                    end
                end
            end
        ";

        let result = parse_source(env, lang, source.to_string());
        assert!(result.is_ok(), "Parsing should handle nested blocks and case statements");
    }

    #[test]
    fn test_parser_concurrency_load() {
        let num_threads = 50;
        let barrier = Arc::new(Barrier::new(num_threads));
        let mut handles = Vec::new();

        for _ in 0..num_threads {
            let c = barrier.clone();
            let handle = thread::spawn(move || {
                c.wait();
                let env = unsafe { rustler::env::OwnedEnv::new().env() };
                let lang = Atom::from_str(env, "elixir").unwrap();
                let source = "defmodule Concurrent do end";

                let result = parse_source(env, lang, source.to_string());
                assert!(result.is_ok());
            });
            handles.push(handle);
        }

        for handle in handles {
            handle.join().expect("Thread failed");
        }
    }

    #[test]
    fn test_pathological_input_depth_limit() {
        let env = mock_env();
        let lang = Atom::from_str(env, "elixir").unwrap();
        // Construct deeply nested structure to trigger depth limit
        let mut source = String::new();
        for _ in 0..200 { source.push_str("if true do "); }
        source.push_str(":ok");
        for _ in 0..200 { source.push_str(" end"); }

        let result = parse_source(env, lang, source);
        assert!(result.is_err(), "Parser should reject extremely deep structures");
    }

    #[test]
    fn test_invalid_language_returns_error() {
        let env = mock_env();
        let lang = Atom::from_str(env, "python").unwrap(); 
        let source = "print('hello')";

        let result = parse_source(env, lang, source.to_string());
        assert!(result.is_err(), "Parser should return error for unsupported language");
    }

    #[test]
    fn test_panic_handling_integrity() {
        let env = mock_env();
        let lang = Atom::from_str(env, "elixir").unwrap();
        let source = "\0".repeat(1000); 

        let result = std::panic::catch_unwind(|| {
            parse_source(env, lang, source)
        });

        assert!(result.is_ok(), "Native panic should be caught and not abort the thread");
    }

    #[test]
    fn test_node_offset_precision() {
        let env = mock_env();
        let lang = Atom::from_str(env, "elixir").unwrap();
        let source = "defmodule Test do\nend";

        let result = parse_source(env, lang, source.to_string());
        assert!(result.is_ok());
    }
}
